(() => {
  const root = document.documentElement;
  const asImage = (b64) => `url("data:image/webp;base64,${b64}")`;
  root.style.setProperty("--v9-art-storage", asImage(""));
  root.style.setProperty("--v9-art-brood", asImage(""));
  root.style.setProperty("--v9-art-synergy", asImage(""));
  root.classList.add("v9-art-ready");
})();
